23	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
24		mux := http.NewServeMux()
25		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
26			respond(w, http.StatusOK, `{"status":"ok"}`)
27		})
28		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
29			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
30			defer cancel()
31			if err := checkDatabase(ctx); err != nil {
32				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
33				return
34			}
35			respond(w, http.StatusOK, `{"status":"ready"}`)
36		})
37	
38		h := &handlers{service: service}
39		mux.HandleFunc("POST /entitlements", h.createEntitlement)
40		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
41		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
42		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
43		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
44		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/reverse", h.reverseReservation)
45		mux.HandleFunc("POST /entitlements/{entitlementID}/adjustments", h.createAdjustment)
46		return mux
47	}
48	
49	type handlers struct {
50		service Service
51	}
52	
53	type createEntitlementRequest struct {
54		EntitlementID string `json:"entitlement_id"`
55		SeatsTotal    *int64 `json:"seats_total"`
56		QuotaTotal    *int64 `json:"quota_total"`
57		ValidFrom     string `json:"valid_from"`
58		ValidTo       string `json:"valid_to"`
59	}
60	
61	func (h *handlers) createEntitlement(w http.ResponseWriter, r *http.Request) {
62		var req createEntitlementRequest
63		if !decode(w, r, &req) {
64			return
65		}
66		validFrom, errFrom := time.Parse(time.RFC3339, req.ValidFrom)
67		validTo, errTo := time.Parse(time.RFC3339, req.ValidTo)
68		if req.ValidFrom == "" || req.ValidTo == "" || errFrom != nil || errTo != nil {
69			respondError(w, &entitlements.Error{
70				Code:    entitlements.CodeInvalidRequest,
71				Message: "valid_from and valid_to must be RFC 3339 timestamps, e.g. 2026-01-01T00:00:00Z",
72			})
73			return
74		}
75		ent, err := h.service.CreateEntitlement(r.Context(), entitlements.CreateEntitlementInput{
76			EntitlementID: req.EntitlementID,
77			SeatsTotal:    req.SeatsTotal,
78			QuotaTotal:    req.QuotaTotal,
79			ValidFrom:     validFrom,
80			ValidTo:       validTo,
81		})
82		if err != nil {
83			respondError(w, err)
84			return
85		}
86		respondJSON(w, http.StatusCreated, ent)
87	}
88	
89	type createReservationRequest struct {
90		ReservationID string `json:"reservation_id"`
91		Amount        *int64 `json:"amount"`
92	}
93	
94	func (h *handlers) createReservation(w http.ResponseWriter, r *http.Request) {
95		var req createReservationRequest
96		if !decode(w, r, &req) {
97			return
98		}
99		if req.Amount == nil {
100			respondError(w, &entitlements.Error{
101				Code:    entitlements.CodeInvalidRequest,
102				Message: "amount is required and must be a positive integer",
103			})
104			return
105		}
106		reservation, created, err := h.service.CreateReservation(
107			r.Context(), r.PathValue("entitlementID"), req.ReservationID, *req.Amount)
108		if err != nil {
109			respondError(w, err)
110			return
111		}
112		status := http.StatusOK
113		if created {
114			status = http.StatusCreated
115		}
116		respondJSON(w, status, reservation)
117	}
118	
119	func (h *handlers) settle(action string) http.HandlerFunc {
120		return func(w http.ResponseWriter, r *http.Request) {
121			reservation, err := h.service.SettleReservation(
122				r.Context(), r.PathValue("entitlementID"), r.PathValue("reservationID"), action)
123			if err != nil {
124				respondError(w, err)
125				return
126			}
127			respondJSON(w, http.StatusOK, reservation)
128		}
129	}
130	
131	type reverseReservationRequest struct {
132		ReversalID string `json:"reversal_id"`
133	}
134	
135	func (h *handlers) reverseReservation(w http.ResponseWriter, r *http.Request) {
136		var req reverseReservationRequest
137		if !decode(w, r, &req) {
138			return
139		}
140		reversal, created, err := h.service.ReverseReservation(
141			r.Context(), r.PathValue("entitlementID"), r.PathValue("reservationID"), req.ReversalID)
142		if err != nil {
143			respondError(w, err)
144			return
145		}
146		status := http.StatusOK
147		if created {
148			status = http.StatusCreated
149		}
150		respondJSON(w, status, reversal)
151	}
152	
153	type createAdjustmentRequest struct {
154		AdjustmentID string `json:"adjustment_id"`
155		Delta        *int64 `json:"delta"`
156		EffectiveAt  string `json:"effective_at"`
157	}
158	
159	func (h *handlers) createAdjustment(w http.ResponseWriter, r *http.Request) {
160		var req createAdjustmentRequest
161		if !decode(w, r, &req) {
162			return
163		}
164		if req.Delta == nil || *req.Delta == 0 {
165			respondError(w, &entitlements.Error{
166				Code:    entitlements.CodeInvalidRequest,
167				Message: "delta is required and must be a non-zero integer",
168			})
169			return
170		}
171		effectiveAt, err := time.Parse(time.RFC3339, req.EffectiveAt)
172		if req.EffectiveAt == "" || err != nil {
173			respondError(w, &entitlements.Error{
174				Code:    entitlements.CodeInvalidRequest,
175				Message: "effective_at must be an RFC 3339 timestamp, e.g. 2026-06-01T00:00:00Z",
176			})
177			return
178		}
179		adjustment, created, err := h.service.CreateAdjustment(
180			r.Context(), r.PathValue("entitlementID"), req.AdjustmentID, *req.Delta, effectiveAt)
181		if err != nil {
182			respondError(w, err)
183			return
184		}
185		status := http.StatusOK
186		if created {
187			status = http.StatusCreated
188		}
189		respondJSON(w, status, adjustment)
190	}
191	
192	func (h *handlers) getEntitlement(w http.ResponseWriter, r *http.Request) {
193		view, err := h.service.GetView(r.Context(), r.PathValue("entitlementID"))
194		if err != nil {
195			respondError(w, err)
196			return
197		}
198		respondJSON(w, http.StatusOK, view)
199	}
200	
201	// decode parses a JSON request body strictly; on failure it writes the error
202	// response and returns false.
203	func decode(w http.ResponseWriter, r *http.Request, target any) bool {
204		decoder := json.NewDecoder(r.Body)
205		decoder.DisallowUnknownFields()
206		if err := decoder.Decode(target); err != nil {
207			respondError(w, &entitlements.Error{
208				Code:    entitlements.CodeInvalidRequest,
209				Message: "request body must be a JSON object with the documented fields",
210			})
211			return false
212		}
213		return true
214	}
215	
216	// errorStatus maps stable domain error codes to HTTP statuses.
217	var errorStatus = map[string]int{
218		entitlements.CodeInvalidRequest:          http.StatusBadRequest,
219		entitlements.CodeEntitlementExists:       http.StatusConflict,
220		entitlements.CodeEntitlementNotFound:     http.StatusNotFound,
221		entitlements.CodeEntitlementNotActive:    http.StatusUnprocessableEntity,
222		entitlements.CodeInsufficientQuota:       http.StatusUnprocessableEntity,
223		entitlements.CodeReservationNotFound:     http.StatusNotFound,
224		entitlements.CodeReservationParamChanged: http.StatusConflict,
225		entitlements.CodeReservationSettled:      http.StatusConflict,
226		entitlements.CodeReservationNotConfirmed: http.StatusUnprocessableEntity,
227		entitlements.CodeReservationReversed:     http.StatusConflict,
228		entitlements.CodeAdjustmentParamChanged:  http.StatusConflict,
229	}
230	
231	func respondError(w http.ResponseWriter, err error) {
232		var domainErr *entitlements.Error
233		if !errors.As(err, &domainErr) {
234			respondJSON(w, http.StatusInternalServerError, map[string]any{
235				"error": map[string]string{"code": "internal", "message": "internal server error"},
236			})
237			return
238		}
239		status, ok := errorStatus[domainErr.Code]
240		if !ok {
241			respondJSON(w, http.StatusInternalServerError, map[string]any{
242				"error": map[string]string{"code": "internal", "message": "internal server error"},
243			})
244			return
245		}
246		respondJSON(w, status, map[string]any{
247			"error": map[string]string{"code": domainErr.Code, "message": domainErr.Message},
248		})
249	}
250	
251	func respondJSON(w http.ResponseWriter, status int, body any) {
252		encoded, err := json.Marshal(body)
253		if err != nil {
254			respond(w, http.StatusInternalServerError, `{"error":{"code":"internal","message":"internal server error"}}`)
255			return
256		}
257		respond(w, status, string(encoded))
258	}
259	
260	func respond(w http.ResponseWriter, status int, body string) {
261		w.Header().Set("Content-Type", "application/json")
262		w.Header().Set("Cache-Control", "no-store")
263		w.WriteHeader(status)
264		_, _ = w.Write([]byte(body + "\n"))
265	}
