643		if view.QuotaTotal != 150 || view.AvailableAmount != 150 {
644			t.Fatalf("quota after immediate adjustment: %+v", view)
645		}
646	
647		// A future adjustment applies once its effective time arrives, even if
648		// nothing but a read touches the entitlement.
649		laterAt := time.Now().Add(1200 * time.Millisecond)
650		if _, _, err := store.CreateAdjustment(ctx, id, "adj-later", 30, laterAt); err != nil {
651			t.Fatalf("create future adjustment: %v", err)
652		}
653		view, _ = store.GetView(ctx, id)
654		if view.QuotaTotal != 150 || view.Adjustments[1].Status != StatusPending {
655			t.Fatalf("adjustment applied before its effective time: %+v", view)
656		}
