658		view, _ = store.GetView(ctx, id)
659		if view.QuotaTotal != 180 || view.AvailableAmount != 180 || len(view.Adjustments) != 2 {
660			t.Fatalf("due adjustment not applied by view: %+v", view)
661		}
662		for _, a := range view.Adjustments {
663			if a.Status != StatusApplied || a.AppliedAt == nil {
664				t.Fatalf("adjustment should be applied: %+v", a)
665			}
666		}
