668		view, _ = store.GetView(ctx, id)
669		if view.QuotaTotal != 180 {
670			t.Fatalf("adjustment applied twice: %+v", view)
671		}
672		replay, created, err := store.CreateAdjustment(ctx, id, "adj-later", 30, laterAt)
673		if err != nil || created || replay.Status != StatusApplied {
674			t.Fatalf("late replay: %+v created=%v err=%v", replay, created, err)
