678			t.Fatalf("late replay applied again: %+v", view)
679		}
680	
681		// The grown total is what reservations are checked against.
682		if _, _, err := store.CreateReservation(ctx, id, "res-1", 180); err != nil {
683			t.Fatalf("reserve against adjusted quota: %v", err)
684		}
