725			t.Fatalf("decrease applied while occupancy too high: %+v", view)
726		}
727	
728		// Reversing the confirmed 60 frees the occupancy; the blocked decrease
729		// takes effect within the same operation, exactly once.
730		if _, _, err := store.ReverseReservation(ctx, id, "res-confirm", "corr-1"); err != nil {
731			t.Fatalf("reverse: %v", err)
