792		past := time.Now().Add(-time.Minute)
793	
794		const workers = 8
795		var wg sync.WaitGroup
796		results := make(chan error, workers*2)
797		for w := 0; w < workers; w++ {
798			wg.Add(1)
799			go func(w int) {
800				defer wg.Done()
801				aid := fmt.Sprintf("adj-%d", w)
802				// Each worker submits one increase and replays it; the replay
803				// races the first submission of other workers.
804				_, _, err := store.CreateAdjustment(ctx, id, aid, 5, past)
805				results <- err
806				_, _, err = store.CreateAdjustment(ctx, id, aid, 5, past)
807				results <- err
808			}(w)
809		}
810		wg.Wait()
811		close(results)
812		for err := range results {
813			if err != nil {
814				t.Fatalf("unexpected concurrent failure: %v", err)
815			}
816		}
817		view, err := store.GetView(ctx, id)
818		if err != nil {
819			t.Fatalf("view: %v", err)
820		}
821		if view.QuotaTotal != quota+workers*5 || len(view.Adjustments) != workers {
822			t.Fatalf("concurrent adjustments broke state: %+v", view)
823		}
824		for _, a := range view.Adjustments {
825			if a.Status != StatusApplied {
826				t.Fatalf("adjustment not applied: %+v", a)
827			}
828		}
829	}
830	
831	func TestAdjustmentsSurviveReconnection(t *testing.T) {
832		store := testStore(t)
833		from, to := activeWindow()
834		id := uniqueID(t)
835		mustCreate(t, store, id, 100, from, to)
836		ctx := context.Background()
837		appliedAt := time.Now().Add(-time.Minute)
838		if _, _, err := store.CreateAdjustment(ctx, id, "adj-applied", 20, appliedAt); err != nil {
839			t.Fatalf("create applied adjustment: %v", err)
840		}
841		pendingAt := time.Now().Add(1200 * time.Millisecond)
842		if _, _, err := store.CreateAdjustment(ctx, id, "adj-pending", 30, pendingAt); err != nil {
843			t.Fatalf("create pending adjustment: %v", err)
844		}
845	
846		// A fresh pool over the same database simulates a service restart.
847		pool, err := pgxpool.New(ctx, os.Getenv("TEST_DATABASE_URL"))
848		if err != nil {
849			t.Fatalf("reconnect: %v", err)
850		}
851		defer pool.Close()
852		restarted := NewStore(pool)
853		view, err := restarted.GetView(ctx, id)
854		if err != nil {
855			t.Fatalf("view after restart: %v", err)
856		}
857		if view.QuotaTotal != 120 || len(view.Adjustments) != 2 ||
858			view.Adjustments[0].Status != StatusApplied || view.Adjustments[1].Status != StatusPending {
859			t.Fatalf("adjustment state lost across restart: %+v", view)
860		}
861	
862		// A replay through the restarted service does not apply again, and a
863		// pending adjustment that came due during the downtime applies once.
864		replay, created, err := restarted.CreateAdjustment(ctx, id, "adj-applied", 20, appliedAt)
865		if err != nil || created || replay.Status != StatusApplied {
866			t.Fatalf("replay after restart: %+v created=%v err=%v", replay, created, err)
867		}
868		time.Sleep(1500 * time.Millisecond)
869		view, _ = restarted.GetView(ctx, id)
870		if view.QuotaTotal != 150 || view.Adjustments[1].Status != StatusApplied {
871			t.Fatalf("due adjustment not applied after restart: %+v", view)
872		}
873	}
