		return Reschedule{}, false, fmt.Errorf("rewrite validity window: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return Reschedule{}, false, fmt.Errorf("commit reschedule: %w", err)
	}
	return created, true, nil
}

